CREATE TABLE IF NOT EXISTS dm_index(id INTEGER PRIMARY KEY,code TEXT UNIQUE NOT NULL,name TEXT NOT NULL,category TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS dm_factor(id INTEGER PRIMARY KEY,name TEXT UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS br_index_factor(index_id INTEGER REFERENCES dm_index(id),factor_id INTEGER REFERENCES dm_factor(id),PRIMARY KEY(index_id,factor_id));
CREATE TABLE IF NOT EXISTS dm_data_source(id INTEGER PRIMARY KEY,index_id INTEGER REFERENCES dm_index(id),url TEXT NOT NULL,expected INTEGER,last_attempt TEXT,last_success TEXT,status TEXT,error TEXT,UNIQUE(index_id,url));
CREATE TABLE IF NOT EXISTS dm_industry(id INTEGER PRIMARY KEY,name TEXT UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS ft_index_snapshot(id INTEGER PRIMARY KEY,index_id INTEGER REFERENCES dm_index(id),source_id INTEGER REFERENCES dm_data_source(id),observed TEXT NOT NULL,sha TEXT NOT NULL,member_count INTEGER NOT NULL,status TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ft_index_event(snapshot_id INTEGER REFERENCES ft_index_snapshot(id),company_id INTEGER REFERENCES dm_company(id),present INTEGER NOT NULL CHECK(present IN (0,1)),PRIMARY KEY(snapshot_id,company_id)) WITHOUT ROWID;
CREATE TABLE IF NOT EXISTS ft_classification_event(snapshot_id INTEGER REFERENCES ft_index_snapshot(id),company_id INTEGER REFERENCES dm_company(id),industry_id INTEGER REFERENCES dm_industry(id),PRIMARY KEY(snapshot_id,company_id)) WITHOUT ROWID;
CREATE TABLE IF NOT EXISTS misc_constituent_reconciliation(source_id INTEGER REFERENCES dm_data_source(id),isin TEXT,symbol TEXT,name TEXT,reason TEXT,observed TEXT,PRIMARY KEY(source_id,isin));
CREATE INDEX IF NOT EXISTS ix_index_snapshot ON ft_index_snapshot(index_id,status,id);
CREATE VIEW IF NOT EXISTS vw_index_membership_history AS WITH e AS (SELECT s.index_id,e.company_id,e.present,s.id snapshot_id,s.observed valid_from,LEAD(s.observed) OVER(PARTITION BY s.index_id,e.company_id ORDER BY s.id) valid_to FROM ft_index_event e JOIN ft_index_snapshot s ON s.id=e.snapshot_id WHERE s.status='COMPLETE') SELECT * FROM e WHERE present=1;
CREATE VIEW IF NOT EXISTS vw_company_index_membership_current AS SELECT h.*,i.code,i.name index_name,i.category,c.symbol,c.isin FROM vw_index_membership_history h JOIN dm_index i ON i.id=h.index_id JOIN dm_company c ON c.id=h.company_id WHERE h.valid_to IS NULL;
CREATE VIEW IF NOT EXISTS vw_company_factor_current AS SELECT DISTINCT m.company_id,m.symbol,f.id factor_id,f.name factor FROM vw_company_index_membership_current m JOIN br_index_factor b ON b.index_id=m.index_id JOIN dm_factor f ON f.id=b.factor_id;
CREATE VIEW IF NOT EXISTS vw_index_constituents AS SELECT * FROM vw_company_index_membership_current;
CREATE VIEW IF NOT EXISTS vw_sector_constituents AS SELECT * FROM vw_index_constituents WHERE category='SECTOR';
CREATE VIEW IF NOT EXISTS vw_factor_constituents AS SELECT * FROM vw_company_factor_current;
CREATE VIEW IF NOT EXISTS vw_company_factor_overlap AS SELECT company_id,symbol,count(*) factor_count FROM vw_company_factor_current GROUP BY company_id,symbol;
CREATE VIEW IF NOT EXISTS vw_sector_factor_overlap AS SELECT s.index_id,s.index_name,f.factor,count(DISTINCT s.company_id) companies FROM vw_sector_constituents s JOIN vw_company_factor_current f ON f.company_id=s.company_id GROUP BY s.index_id,s.index_name,f.factor;
CREATE VIEW IF NOT EXISTS vw_index_membership_changes AS SELECT s.index_id,e.company_id,s.observed,CASE e.present WHEN 1 THEN 'ADDED' ELSE 'REMOVED' END change_type FROM ft_index_event e JOIN ft_index_snapshot s ON s.id=e.snapshot_id WHERE s.status='COMPLETE';
CREATE VIEW IF NOT EXISTS vw_index_membership_additions AS SELECT * FROM vw_index_membership_changes WHERE change_type='ADDED';
CREATE VIEW IF NOT EXISTS vw_index_membership_removals AS SELECT * FROM vw_index_membership_changes WHERE change_type='REMOVED';
CREATE VIEW IF NOT EXISTS vw_company_industry_current AS WITH r AS (SELECT e.company_id,e.industry_id,s.observed,ROW_NUMBER() OVER(PARTITION BY e.company_id ORDER BY s.id DESC) rn FROM ft_classification_event e JOIN ft_index_snapshot s ON s.id=e.snapshot_id WHERE s.status='COMPLETE') SELECT r.company_id,d.name industry,r.observed FROM r JOIN dm_industry d ON d.id=r.industry_id WHERE rn=1;
CREATE VIEW IF NOT EXISTS vw_company_membership_summary AS SELECT c.id company_id,c.symbol,c.name,COALESCE(d.industry,c.industry) industry,(SELECT group_concat(index_name) FROM vw_sector_constituents m WHERE m.company_id=c.id) sector_indices,(SELECT group_concat(factor) FROM vw_company_factor_current f WHERE f.company_id=c.id) factors,(SELECT group_concat(index_name) FROM vw_index_constituents m WHERE m.company_id=c.id AND category='THEMATIC') thematic_indices,(SELECT group_concat(index_name) FROM vw_index_constituents m WHERE m.company_id=c.id AND category='BENCHMARK') benchmarks FROM dm_company c LEFT JOIN vw_company_industry_current d ON d.company_id=c.id;
CREATE VIEW IF NOT EXISTS vw_company_fundamental_membership AS SELECT m.*,EXISTS(SELECT 1 FROM dm_snapshot s WHERE s.company_id=m.company_id AND s.status='COMPLETE' AND EXISTS(SELECT 1 FROM ft_source_reference r WHERE r.snapshot_id=s.id)) has_financials FROM vw_company_membership_summary m;
CREATE VIEW IF NOT EXISTS vw_index_source_health AS SELECT i.code,i.name,i.category,d.* FROM dm_data_source d JOIN dm_index i ON i.id=d.index_id;
CREATE VIEW IF NOT EXISTS vw_index_acquisition_progress AS SELECT category,COALESCE(status,'PENDING') status,count(*) sources FROM vw_index_source_health GROUP BY category,status;
CREATE VIEW IF NOT EXISTS vw_company_sector_current AS SELECT DISTINCT company_id,symbol,index_id,index_name sector_index FROM vw_sector_constituents;
CREATE VIEW IF NOT EXISTS vw_company_classification_history AS SELECT e.company_id,d.name industry,s.observed valid_from,LEAD(s.observed) OVER(PARTITION BY e.company_id ORDER BY s.id) valid_to FROM ft_classification_event e JOIN ft_index_snapshot s ON s.id=e.snapshot_id JOIN dm_industry d ON d.id=e.industry_id WHERE s.status='COMPLETE';
